[Form]
public class ResReservationScreen extends FormRun
{
    boolean historyVisible;
}

public void init()
{
    super();

    FilterGroup_DateFrom.dateValue(DateTimeUtil::date(DateTimeUtil::utcNow()));
    FilterGroup_DateTo.dateValue(DateTimeUtil::date(DateTimeUtil::utcNow()) + 30);

    // ReserveButton/UnreserveButton/ToggleHistoryButton are plain Button
    // controls, and SetupButton's own automatic security trim is not
    // re-evaluated by the framework either -- worse, selecting 2+ rows in
    // the Demands grid forces ALL FOUR to disabled by default (standard
    // ActionPane behavior once a grid enters genuine multi-selection)
    // unless explicitly re-asserted. updateActionPaneForSelection() sets
    // the correct baseline here and is re-run from ResDemandLineTmp's
    // active() below every time the selection changes, so it stays
    // correct through single- and multi-select alike.
    element.updateActionPaneForSelection();

    // History is hidden by default -- ToggleHistoryButton controls it from here on.
    historyVisible = false;
    this.updateHistoryVisibility();

    // Order Type defaults to All, so the Order filter starts disabled --
    // see updateOrderFilterEnabled().
    this.updateOrderFilterEnabled();

    element.refreshDemands();
}

/// <summary>
/// ReserveButton/UnreserveButton are plain Button controls, not
/// MenuItemButtons -- unlike SetupButton, they have no entry point of
/// their own for the security framework to trim automatically. A user
/// holding only <c>ResReservationScreen_DM_View</c> (Read) on this
/// screen's entry point must not be able to execute a reservation, which
/// requires <c>ResReservationScreen_AM_Execute</c> (Update).
/// </summary>
private boolean canExecuteReservations()
{
    SecurityRights securityRights = SecurityRights::construct();

    // ResReservationScreen_DM_View grants Read (-> AccessRight::View) and
    // ResReservationScreen_AM_Execute grants Read+Update (-> AccessRight::Edit)
    // on the same ResReservationScreen entry point -- Edit is what
    // distinguishes a user who can actually execute a reservation.
    return securityRights.menuItemAccessRight(SecurableType::MenuItemDisplay, menuItemDisplayStr(ResReservationScreen)) >= AccessRight::Edit;
}

/// <summary>
/// Mirrors the framework's own automatic trim for SetupButton (a
/// MenuFunctionButton to the ResSetupDialog Display menu item, normally
/// auto-enabled/disabled by View access on it) so that trim can be
/// re-asserted from updateActionPaneForSelection() after a multi-select
/// forces it to disabled -- without granting anything the framework
/// itself would not have already granted.
/// </summary>
private boolean canOpenSetup()
{
    SecurityRights securityRights = SecurityRights::construct();

    return securityRights.menuItemAccessRight(SecurableType::MenuItemDisplay, menuItemDisplayStr(ResSetupDialog)) >= AccessRight::View;
}

/// <summary>
/// Selecting 2+ Demand lines forces every ActionPane button to disabled
/// by default (standard behavior once a grid enters genuine
/// multi-selection) unless the form explicitly re-enables the ones that
/// should stay usable. Reserve/Unreserve are designed to run against a
/// multi-selection (see selectedDemandRecIds()), so they stay enabled
/// per the user's own privilege regardless of how many lines are marked;
/// Setup has nothing to do with Demand selection at all, so it is
/// likewise re-asserted per its own privilege. History only ever shows
/// the single active line's audit trail (refreshHistoryForSelection()
/// filters to exactly one line), so it is deliberately left disabled
/// while more than one line is marked -- there is no single line's
/// history to show in that state.
/// </summary>
public void updateActionPaneForSelection()
{
    Array   marked          = this.demandDs().recordsMarked();
    boolean multiSelected   = marked && marked.lastIndex() > 1;

    ReserveButton.enabled(this.canExecuteReservations());
    UnreserveButton.enabled(this.canExecuteReservations());
    SetupButton.enabled(this.canOpenSetup());
    ToggleHistoryButton.enabled(!multiSelected);
}

/// <summary>
/// Applies the current <c>historyVisible</c> state to the History pane,
/// its splitters (above and below), the bottom filler, and the toggle
/// button's own label.
/// </summary>
private void updateHistoryVisibility()
{
    HistoryTab.visible(historyVisible);
    MainHistorySplitter.visible(historyVisible);
    BottomSplitter.visible(historyVisible);
    BottomFiller.visible(historyVisible);

    ToggleHistoryButton.text(historyVisible
        ? "@ResReservation:ResReservationScreen_HideHistory"
        : "@ResReservation:ResReservationScreen_ShowHistory");
}

/// <summary>
/// The Order filter only makes sense once a specific order type is chosen
/// -- a single order id can't be both a SalesId and a TransferId, so
/// there is no single id space to filter against when Order Type is All.
/// Disables (and clears) the field in that case; <c>FilterGroup_Order</c>'s
/// own <c>lookup()</c> then scopes the dropdown to open Sales orders or
/// open Transfer orders depending on whichever type is selected.
/// </summary>
private void updateOrderFilterEnabled()
{
    boolean enabled = FilterGroup_OrderType.selection() != ResOrderTypeFilter::All;

    FilterGroup_Order.enabled(enabled);

    if (!enabled)
    {
        FilterGroup_Order.text('');
    }
}

/// <summary>
/// The Demands FormDataSource, fetched explicitly. Bare implicit access to a
/// datasource by name is only reliably in scope inside that datasource's own
/// methods or a control's own methods -- not the form's top-level methods,
/// unless the datasource happens to share the form's name (ours don't).
/// </summary>
private FormDataSource demandDs()
{
    return element.dataSource(tableStr(ResDemandLineTmp));
}

private FormDataSource supplyDs()
{
    return element.dataSource(tableStr(ResSupplyLineTmp));
}

private FormDataSource historyDs()
{
    return element.dataSource(tableStr(ResHistoryLog));
}

/// <summary>
/// Re-runs the Demands query from the current filter fields (Refresh and
/// Filter buttons; also called on load), then re-scopes the Supplies grid
/// to whichever Demand line ends up selected (or clears it, if none does).
/// </summary>
public void refreshDemands()
{
    FormDataSource      demandDs     = this.demandDs();

    ResDemandProvider::run(
        demandDs.cursor(),
        FilterGroup_Site.text(),
        FilterGroup_Warehouse.text(),
        FilterGroup_Item.text(),
        FilterGroup_DateFrom.dateValue(),
        FilterGroup_DateTo.dateValue(),
        FilterGroup_OrderType.selection(),
        FilterGroup_Order.text());

    demandDs.executeQuery();

    // demandDs.executeQuery() already fires ResDemandLineTmp's active(),
    // which calls this for the new current row -- but calling it again
    // explicitly here also covers the case where the query comes back
    // empty (no active row to fire active() against), so the Supplies
    // grid still ends up correctly scoped/cleared either way.
    element.refreshSuppliesForSelection();
    element.refreshHistoryForSelection();
}

/// <summary>
/// Narrows the Supplies grid to the EXACT item/site/warehouse of whichever
/// Demand row(s) are currently selected -- the FDD's "auto-highlighting of
/// matching Supply rows". Previously this scoped by item only and fell back
/// to the screen's Site/Warehouse filter fields (no restriction when blank),
/// which could show supply from a different site/warehouse than the
/// selected Demand line's own -- supply Reserve could never actually use,
/// since <c>ResReservationEngine.eligibleSupplyRecIds()</c> always filters
/// strictly to the demand line's own site/warehouse.
/// </summary>
public void refreshSuppliesForSelection()
{
    FormDataSource          supplyDs        = this.supplyDs();
    ResSupplyLineTmp        supplyBuffer    = supplyDs.cursor();
    container               selectedRecIds  = this.selectedDemandRecIds(false);

    ResSupplyProvider::runForSelectedDemand(supplyBuffer, this.demandDs().cursor(), selectedRecIds);

    supplyDs.executeQuery();
}

/// <summary>
/// Narrows the History grid to the exact demand line currently active, so a
/// user can see -- for the specific order/line they just reserved or
/// unreserved -- which batch/supply record the engine actually used
/// (<c>ResHistoryLog.BatchId</c>/<c>RuleApplied</c>, written by
/// <c>ResReservationEngine.commitReservation</c>).
/// </summary>
public void refreshHistoryForSelection()
{
    FormDataSource          historyDs     = this.historyDs();
    ResDemandLineTmp        demandLineTmp = this.demandDs().cursor();
    QueryBuildDataSource    qbds          = historyDs.query().dataSourceTable(tableNum(ResHistoryLog));

    qbds.clearRanges();

    if (demandLineTmp.RecId)
    {
        qbds.addRange(fieldNum(ResHistoryLog, OrderType)).value(queryValue(demandLineTmp.OrderType));
        qbds.addRange(fieldNum(ResHistoryLog, OrderId)).value(queryValue(demandLineTmp.OrderId));
        qbds.addRange(fieldNum(ResHistoryLog, LineNum)).value(queryValue(demandLineTmp.LineNum));
    }
    else
    {
        qbds.addRange(fieldNum(ResHistoryLog, RecId)).value(queryValue(0));
    }

    historyDs.executeQuery();
}

private container selectedDemandRecIds(boolean _reservedOnly)
{
    MultiSelectionHelper    selectionHelper = MultiSelectionHelper::construct();
    ResDemandLineTmp        demandLineTmp;
    container               recIds;

    selectionHelper.parmDatasource(this.demandDs());
    demandLineTmp = selectionHelper.getFirst();

    while (demandLineTmp)
    {
        if (!_reservedOnly || demandLineTmp.ReservedQty > 0)
        {
            recIds += demandLineTmp.RecId;
        }

        demandLineTmp = selectionHelper.getNext();
    }

    return recIds;
}

public void reserveSelected()
{
    container               selectedRecIds = this.selectedDemandRecIds(false);
    ResReservationEngine     engine;

    if (!conLen(selectedRecIds))
    {
        warning("@ResReservation:ResReservationScreen_NoLinesSelected");
        return;
    }

    engine = ResReservationEngine::construct();
    engine.reserve(this.demandDs().cursor(), selectedRecIds);

    info(strFmt(
        "@ResReservation:ResReservationScreen_ReserveSummary",
        engine.parmLinesFullyReserved(),
        engine.parmLinesPartiallyReserved(),
        engine.parmLinesSkipped()));

    element.refreshDemands();
}

/// <summary>
/// The reason dialog is received as a plain <c>FormRun</c> (never as its own
/// specific form class) -- that is the pattern used consistently throughout the
/// standard product for launching a modal dialog from another form's code.
/// The reason code/comment come back via <c>args.parmObject()</c>, a container
/// of [reasonCode, comment], set by the dialog's OK button before it closes.
/// </summary>
public void unreserveSelected()
{
    container               selectedRecIds = this.selectedDemandRecIds(true);
    Args                     args;
    ClassFactory             factory;
    FormRun                  reasonDialog;
    ResReservationEngine     engine;
    ContainerClass           resultWrapper;
    container                result;

    if (!conLen(selectedRecIds))
    {
        warning("@ResReservation:ResReservationScreen_NoReservedLinesSelected");
        return;
    }

    args = new Args(formStr(ResUnreserveReasonDialog));
    factory = new ClassFactory();
    reasonDialog = factory.formRunClass(args);
    reasonDialog.init();
    reasonDialog.run();
    reasonDialog.wait();

    if (reasonDialog.closedOk())
    {
        resultWrapper = args.parmObject();
        result = resultWrapper.value();

        engine = ResReservationEngine::construct();
        engine.unreserve(
            this.demandDs().cursor(),
            selectedRecIds,
            conPeek(result, 1),
            conPeek(result, 2));

        info(strFmt("@ResReservation:ResReservationScreen_UnreserveSummary", conLen(selectedRecIds)));

        element.refreshDemands();
    }
}

public int active()
{
    int ret = super();

    element.refreshSuppliesForSelection();
    element.refreshHistoryForSelection();
    element.updateActionPaneForSelection();

    return ret;
}

public void displayOption(Common _record, FormRowDisplayOption _options)
{
    ResDemandLineTmp demandLineTmp = _record;

    super(_record, _options);

    switch (demandLineTmp.RiskIndicator)
    {
        case ResRiskIndicator::Red:
            _options.backColor(WinApi::RGB2int(255, 199, 206));
            break;
        case ResRiskIndicator::Yellow:
            _options.backColor(WinApi::RGB2int(255, 235, 156));
            break;
        case ResRiskIndicator::Green:
            _options.backColor(WinApi::RGB2int(198, 239, 206));
            break;
    }
}

public void init()
{
    super();

    this.query().dataSourceTable(tableNum(ResHistoryLog)).addSortField(fieldNum(ResHistoryLog, RecId), SortOrder::Descending);
}

public void clicked()
{
    super();

    element.refreshDemands();
}

public void clicked()
{
