/// <summary>
/// InventTransRefId is a generic reference id (shared by SalesId,
/// TransferId, PurchId, ProdId, ...) with no lookup of its own.
/// Scope the dropdown to whichever order type is currently selected
/// in FilterGroup_OrderType, showing only open orders -- same
/// "open" definition ResDemandProvider uses to build the Demands
/// grid (RemainInventPhysical &gt; 0 for Sales, QtyRemainShip &gt; 0
/// for Transfer). Order Type = All has no single id space to look
/// up against, and the field is disabled in that state anyway (see
/// element.updateOrderFilterEnabled()).
/// </summary>
public void lookup()
{
    Query                   query;
    QueryBuildDataSource     qbdsHeader;
    QueryBuildDataSource     qbdsLine;
    SysTableLookup           sysTableLookup;

    switch (FilterGroup_OrderType.selection())
    {
        case ResOrderTypeFilter::Sales:
            sysTableLookup = SysTableLookup::newParameters(tableNum(SalesTable), this);
            sysTableLookup.addLookupfield(fieldNum(SalesTable, SalesId));
            sysTableLookup.addLookupfield(fieldNum(SalesTable, CustAccount));
            sysTableLookup.addLookupfield(fieldNum(SalesTable, SalesName));

            query = new Query();
            qbdsHeader = query.addDataSource(tableNum(SalesTable));
            qbdsHeader.addRange(fieldNum(SalesTable, SalesStatus)).value(strFmt('!%1', enum2int(SalesStatus::Canceled)));
            qbdsHeader.addRange(fieldNum(SalesTable, DocumentStatus)).value(strFmt('!%1', enum2int(DocumentStatus::Quotation)));

            qbdsLine = qbdsHeader.addDataSource(tableNum(SalesLine));
            qbdsLine.relations(true);
            qbdsLine.joinMode(JoinMode::ExistsJoin);
            qbdsLine.addRange(fieldNum(SalesLine, RemainInventPhysical)).value('>0');

            sysTableLookup.parmQuery(query);
            sysTableLookup.performFormLookup();
            break;

        case ResOrderTypeFilter::Transfer:
            sysTableLookup = SysTableLookup::newParameters(tableNum(InventTransferTable), this);
            sysTableLookup.addLookupfield(fieldNum(InventTransferTable, TransferId));
            sysTableLookup.addLookupfield(fieldNum(InventTransferTable, InventLocationIdFrom));
            sysTableLookup.addLookupfield(fieldNum(InventTransferTable, InventLocationIdTo));

            query = new Query();
            qbdsHeader = query.addDataSource(tableNum(InventTransferTable));

            qbdsLine = qbdsHeader.addDataSource(tableNum(InventTransferLine));
            qbdsLine.relations(true);
            qbdsLine.joinMode(JoinMode::ExistsJoin);
            qbdsLine.addRange(fieldNum(InventTransferLine, QtyRemainShip)).value('>0');

            sysTableLookup.parmQuery(query);
            sysTableLookup.performFormLookup();
            break;

        default:
            super();
    }
}

